def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    boxes = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 7 and (r, c) not in seen:
                stack = [(r, c)]
                seen.add((r, c))
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny, nx = y+dy, x+dx
                        if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 7 and (ny, nx) not in seen:
                            seen.add((ny, nx))
                            stack.append((ny, nx))
                top = min(y for y,x in cells)
                left = min(x for y,x in cells)
                bottom = max(y for y,x in cells)
                right = max(x for y,x in cells)
                boxes.append((top, left, bottom, right))
    oh = max(b-t for t,l,b,r in boxes) + 1
    ow = max(r-l for t,l,b,r in boxes) + 1
    out = [[7]*ow for _ in range(oh)]
    for top, left, bottom, right in boxes:
        for y in range(top, bottom+1):
            for x in range(left, right+1):
                if grid[y][x] not in (0, 7) and grid[y][x] != grid[0][0]:
                    out[y-top][x-left] = grid[y][x]
    return out
